import{_ as t,o as a,c as h,a2 as i}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"Ví dụ: ba chân dung khác nhau","description":"","frontmatter":{},"headers":[],"relativePath":"portrait/vi-du.md","filePath":"portrait/vi-du.md"}'),c={name:"portrait/vi-du.md"};function r(e,n,g,o,u,l){return a(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="vi-du-ba-chan-dung-khac-nhau" tabindex="-1">Ví dụ: ba chân dung khác nhau <a class="header-anchor" href="#vi-du-ba-chan-dung-khac-nhau" aria-label="Permalink to &quot;Ví dụ: ba chân dung khác nhau&quot;">​</a></h1><p>Trên trang này# Ví dụ: ba chân dung khác nhau <a href="#vi-du-ba-chan-dung-khac-nhau">​</a> Nemo12 cho mỗi learner tối đa ba Portrait cùng lúc — cố ý. Ba kịch bản đặt cạnh nhau khiến gia đình phải nói ra điều mình thật sự ưu tiên, thay vì mặc định đi theo con đường quen thuộc nhất. Dưới đây là ba chân dung cho cùng một learner giả định: An, lớp 8, học khá đều, thích đọc, chơi bóng rổ, hay ngại phát biểu.</p><h2 id="portrait-1-—-academic-excellence-​" tabindex="-1">Portrait 1 — Academic Excellence <a href="#portrait-1-—-academic-excellence">​</a> <a class="header-anchor" href="#portrait-1-—-academic-excellence-​" aria-label="Permalink to &quot;Portrait 1 — Academic Excellence [​](#portrait-1-—-academic-excellence)&quot;">​</a></h2><p>MảngNội dungAcademicThi chuyên Toán; giữ vững top đầu ở trườngCapabilitiesGiải quyết vấn đề khó; chịu được áp lực dàiLanguagesTiếng Anh học thuật đủ để đọc tài liệuSportsBóng rổ giữ ở mức giải trí, 1 buổi/tuầnPersonalKỷ luật tự giác; quen với lịch dàyExperiencesTrại hè Toán; một kỳ thi quốc gia<strong>Milestone chính:</strong> thi thử chuyên 03/2027 · thi chuyên 06/2027. <strong>Cái giá:</strong> khoảng 12–15 giờ học mỗi tuần ngoài giờ trường. Bóng rổ giảm. Rủi ro rõ: nếu trượt, ba năm chỉ có một câu chuyện, và câu chuyện đó kết thúc bằng thất bại.</p><h2 id="portrait-2-—-balanced-explorer-​" tabindex="-1">Portrait 2 — Balanced Explorer <a href="#portrait-2-—-balanced-explorer">​</a> <a class="header-anchor" href="#portrait-2-—-balanced-explorer-​" aria-label="Permalink to &quot;Portrait 2 — Balanced Explorer [​](#portrait-2-—-balanced-explorer)&quot;">​</a></h2><p>MảngNội dungAcademicHọc chắc chương trình, không hổng; vào một trường tốt không chuyênCapabilitiesTự quản lý việc học; trình bày được ý của mìnhLanguagesIELTS 7.0 trước lớp 11; tiếng Trung giao tiếp cơ bảnSportsBóng rổ trong đội trường, 3 buổi/tuầnCreativeGuitar; viết blog về sách đã đọcPersonal<strong>Bớt ngại phát biểu</strong> — mốc cụ thể, có theo dõiExperiencesMột chuyến đi không có bố mẹ; một dự án tự làm<strong>Milestone chính:</strong> IELTS 6.5 vào 06/2027 · thuyết trình trước lớp 3 lần trong năm học · hoàn thành một dự án cá nhân. <strong>Cái giá:</strong> không có huy chương nào để khoe. Với những gia đình quen so sánh, đây là cái giá thật và cần được nói ra.</p><h2 id="portrait-3-—-independent-builder-​" tabindex="-1">Portrait 3 — Independent Builder <a href="#portrait-3-—-independent-builder">​</a> <a class="header-anchor" href="#portrait-3-—-independent-builder-​" aria-label="Permalink to &quot;Portrait 3 — Independent Builder [​](#portrait-3-—-independent-builder)&quot;">​</a></h2><p>MảngNội dungAcademicĐủ chắc để không đóng cửa nào; không đặt mục tiêu thứ hạngCapabilitiesTự học một kỹ năng mới không cần lớp; làm ra sản phẩm hoàn chỉnhLanguagesTiếng Anh đủ để đọc tài liệu kỹ thuật và xem hướng dẫnCreativeLập trình; làm một trò chơi nhỏ; dựng videoPersonalDám công bố thứ mình làm dù chưa hoàn hảoCareerChưa xác định — <strong>cố ý để mở****Milestone chính:</strong> một sản phẩm có người ngoài dùng trong năm nay · tự học xong một khoá online không bỏ dở. <strong>Cái giá:</strong> ít đảm bảo nhất trong ba phương án. Đòi hỏi bố mẹ chịu được cảm giác bất định trong khi các gia đình xung quanh đều có lộ trình rõ ràng.</p><h2 id="đieu-xay-ra-khi-đat-ba-cai-canh-nhau-​" tabindex="-1">Điều xảy ra khi đặt ba cái cạnh nhau <a href="#đieu-xay-ra-khi-đat-ba-cai-canh-nhau">​</a> <a class="header-anchor" href="#đieu-xay-ra-khi-đat-ba-cai-canh-nhau-​" aria-label="Permalink to &quot;Điều xảy ra khi đặt ba cái cạnh nhau [​](#đieu-xay-ra-khi-đat-ba-cai-canh-nhau)&quot;">​</a></h2><p><strong>Ưu tiên thật lộ ra.</strong> Rất khó nói &quot;cái nào cũng quan trọng&quot; khi phải xếp ba bản này theo thứ tự. <strong>Bố và mẹ có thể chọn khác nhau.</strong> Đây chính là giá trị. Bất đồng này vốn đã tồn tại; giờ nó ra khỏi tình huống cãi nhau về một quyết định cụ thể và trở thành một cuộc trò chuyện về hướng đi. <strong>Con có ý kiến.</strong> An đọc cả ba và đánh dấu từng phần: <em>đồng ý · chưa chắc · không đồng ý</em>. Nếu An đánh &quot;không đồng ý&quot; cho toàn bộ Portrait 1 trong khi bố mẹ xếp nó số một — đó là thông tin quan trọng nhất mà cả nhà thu được trong năm nay. <strong>Có thể trộn.</strong> Kết quả thường không phải chọn một, mà là: <em>&quot;lấy trục học thuật của bản 1, phần cá nhân của bản 2, và giữ dự án cá nhân của bản 3&quot;</em>. Ba bản là công cụ để nghĩ, không phải ba lựa chọn loại trừ nhau.</p><h2 id="đieu-nemo12-lam-voi-ba-ban-nay-​" tabindex="-1">Điều Nemo12 làm với ba bản này <a href="#đieu-nemo12-lam-voi-ba-ban-nay">​</a> <a class="header-anchor" href="#đieu-nemo12-lam-voi-ba-ban-nay-​" aria-label="Permalink to &quot;Điều Nemo12 làm với ba bản này [​](#đieu-nemo12-lam-voi-ba-ban-nay)&quot;">​</a></h2><p>Hệ thống hiển thị <strong>mức đồng thuận</strong> trên từng mảng: chỗ nào cả nhà đồng ý, chỗ nào lệch nhau. Không có phán xét ai đúng, không có gợi ý &quot;nên chọn bản nào&quot;. Với những mảng lệch nhau nhiều, hệ thống gợi ý mở một cuộc trò chuyện — và chỉ dừng ở đó. Việc quyết định tương lai của một đứa trẻ không phải việc của một hệ thống phần mềm. Nếu bạn chỉ làm một Portrait Rất có khả năng nó sẽ là bản gần nhất với con đường mặc định trong đầu bạn. Sức mạnh của ba bản nằm ở chỗ nó buộc bạn phải hình dung nghiêm túc hai tương lai mà bạn vốn sẽ không bao giờ cân nhắc. Ba chân dung không phải để chọn một. Chúng để cả nhà biết mình đang đánh đổi cái gì lấy cái gì. <a href="/ideas/">Sang nhóm: Education Ideas →</a></p>',12)])])}const b=t(c,[["render",r]]);export{d as __pageData,b as default};
